/* ============================================
   New Homepage Layout (post-refactor)
   ============================================ */

/* Section Shell - generic content section */
.section-shell {
    padding: 80px 20px;
    max-width: 1100px;
    margin: 0 auto;
}

/* Section lead text */
.section-lead {
    text-align: center;
    color: var(--text-light);
    font-size: 1.1rem;
    max-width: 640px;
    margin: 0 auto 50px;
    line-height: 1.7;
}

/* Choice Grid - 3 starting point cards */
.choice-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    max-width: 1100px;
    margin: 0 auto;
}

.choice-card {
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 35px 30px;
    box-shadow: var(--shadow-sm);
    transition: all 0.3s ease;
}

.choice-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
    border-color: rgba(42, 82, 152, 0.2);
}

.choice-card h3 {
    font-size: 1.2rem;
    color: var(--primary);
    margin-bottom: 12px;
    font-family: 'Inter', sans-serif;
    font-weight: 600;
}

.choice-card p {
    color: var(--text-light);
    font-size: 0.95rem;
    margin-bottom: 16px;
    line-height: 1.6;
}

.choice-card ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.choice-card ul li {
    color: var(--text);
    font-size: 0.9rem;
    padding: 6px 0;
    padding-left: 20px;
    position: relative;
}

.choice-card ul li::before {
    content: '✓';
    position: absolute;
    left: 0;
    color: var(--success);
    font-weight: bold;
}

/* Band - colored background section */
.band {
    background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
    color: white;
    padding: 80px 20px;
}

.band .section-title {
    color: white;
}

.band .section-lead {
    color: rgba(255,255,255,0.85);
}

